# -- _session_response_to_row -------------------------------------------------


class TestSessionResponseToRow:
    """Test _session_response_to_row helper."""

    def test_maps_fields_with_defaults(self) -> None:
        resp = {
            "session_id": "abc-123",
            "cwd": "/home/user/project",
            "started_at": 1712900000000,
        }
        row = _session_response_to_row(resp)
        assert row["session_id"] == "abc-123"
        assert row["cwd"] == "/home/user/project"
        assert row["started_at"] == 1712900000000
        assert row["model_display_name"] == ""
        assert row["total_cost_usd"] == 0.0
        assert row["total_input_tokens"] == 0
        assert row["total_output_tokens"] == 0
        assert row["context_used_pct"] == 0
        assert row["lines_added"] == 0
        assert row["lines_removed"] == 0
        assert row["ended_at"] == 0
        assert row["pid"] == 0
        assert row["source_system"] == ""
        assert row["last_event_at"] == 0.0

    def test_captures_process_identity_fields(self) -> None:
        resp = {
            "session_id": "abc-123",
            "cwd": "/tmp",
            "started_at": 1712900000000,
            "pid": 4242,
            "source_system": "workstation",
            "last_event_at": 1712900500.5,
        }
        row = _session_response_to_row(resp)
        assert row["pid"] == 4242
        assert row["source_system"] == "workstation"
        assert row["last_event_at"] == 1712900500.5

    def test_converts_ended_at_to_ms(self) -> None:
        resp = {
            "session_id": "abc-123",
            "cwd": "/tmp",
            "started_at": 1712900000000,
            "ended_at": 1712903600.123,
        }
        row = _session_response_to_row(resp)
        assert row["ended_at"] == 1712903600123

    def test_computes_duration_ms(self) -> None:
        import time

        now_ms = int(time.time() * 1000)
        resp = {
            "session_id": "s1",
            "cwd": "/tmp",
            "started_at": now_ms - 120_000,  # 2 minutes ago (in ms)
        }
        row = _session_response_to_row(resp)
        # Duration should be approximately 120_000 ms (allow 2s tolerance)
        assert 118_000 <= row["total_duration_ms"] <= 122_000


