class TestHandleWsMessage:
    """Test _handle_ws_message (pure logic, no I/O)."""

    def _make_client(self) -> AgentPulseClient:
        root = MagicMock()
        client = AgentPulseClient.__new__(AgentPulseClient)
        client._root = root
